import logging

logger = logging.getLogger(APP_NAME)

class Object:
    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path

        if os.path.isdir(self.path):
            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None

            # Try to guess file mime type using file extension
            mime = __get_mime_type(path)

            # If file extension failed to identify file type, read file header to get an idea
            if not mime or mime == 'application/octet-stream':
                mime = __get_mime_type_using_header(path)

            self.type = mime

    @staticmethod
    def get_objects(path):
        objects = []

        if path:
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                objects.append(Object(object_path))

        return objects

@staticmethod
def __get_mime_type(path):
    # Try to identify file by its extension
    mime = mimetypes.guess_type(path)[0]
    logger.debug('Mime type of "{0}" is "{1}"'.format(path, mime))

    return mime

@staticmethod
def __get_mime_type_using_header(path):
    # Try to identify file by its header
    try:
        f = open(path, 'rb')
        image_type = imghdr.what(f)

        if image_type:
            mime = 'image/' + image_type
        else:
            mime = None
    except IOError:
        mime = None

    logger.debug('Mime type of "{0}" using header is "{1}"'.format(path, mime))

    return mime

