from chainer import cuda
from chainer import function
from chainer.utils import type_check

import unittest


class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_type_forward(self, in_types):
        type_check.expect(in_types.size() == 1)

    def check_type_backward(self, in_types, out_types):
        type_check.expect(out_types.size() == 1)

    def check_type_output(self, in_type, out_device):
        try:
            in_type.check_device(out_device)
        except type_check.DeviceTypeMismatch:
            if isinstance(out_device, cuda.Device):
                raise type_check.DeviceTypeMismatch(
                    'Expected out_device for Layer {} is host.'.format(self))
            unknown_dev = out_device
            raise type_check.DeviceTypeMismatch(
                'Unknown device {} for Layer {}'.format(unknown_dev, self))

    def check_backward_data_type(self, in_data, out_data):
        if in_data.dtype != out_data.dtype:
            raise type_check.UserOutputTypeError(
                'Detected wrong output dtype in Layer {}.'
                ' Input dtype: {}, Output dtype: {}.'.format(
                    self, in_data.dtype, out_data.dtype))

    def check_backward_device_type(self, in_data, out_data):
        try:
            in_data_device = cuda.Device(in_data)
            out_data_device = cuda.Device(out_data)
            in_data_device.check_device(out_data_device)
        except type_check.DeviceTypeMismatch:
            if isinstance(cuda.Device(in_data), cuda.CpuDevice):
                raise type_check.DeviceTypeMismatch(
                    'Expected DeviceType of data on the output of Layer {}'
                    ' to be host.'.format(self))
            raise type_check.DeviceTypeMismatch(
                'Expected DeviceType of data on the output of Layer {}'
                ' to be compatible with that on the input.'.format(self))

    def check_backward(self, x_data, gys):
        if not self.out_device:
            return

        x = cuda.to_gpu(x_data)
        h = copy(x, dst=self.out_device)

        self.check_backward_data_type(x_data, h.data)
        self.check_backward_device_type(x_data, h.data)

    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return cuda.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return cuda.copy(gy[0], out_device=cuda.get_device(x[0])),


def copy(x, dst):
    """Copies the input variable onto the specified device.

    This function copies the array of input variable onto the device specified
    by ``dst`` if the original array is on GPU, and otherwise just copies the
    array within host memory.

    Args:
        x (~chainer.Variable): Variable to be copied.
        dst: Target device specifier.

    Returns:
        ~chainer.Variable: Output variable.

    """
    return Copy(dst)(x)


@unittest.skipUnless(
    [cuda.cupy, cuda.chainerx],
    'cupy and chainerx are available')
class TestCopy(unittest.TestCase):

    def test(self):
        x = cuda.cupy.ones((2, 3)).astype('f')
        h = copy(x, dst=0)
        self.assertEqual(h.device, cuda.Device(0))
        self.assertTrue(cuda.cupy.allclose(h.data, 1))


var_tester = unittest.runner.TextTestRunner()
var_tester.run(type_check.generate_test_module(Copy, 'copy'))

