import os
import urllib
import mimetypes
import logging
import re

logger = logging.getLogger(APP_NAME)
YIN_FILE_REGEX = re.compile('^.+\.yin$')

def type_from_extension(path):
    mime = mimetypes.MimeTypes()
    which = mime.guess_type(urllib.pathname2url(path))
    return which[0]

def infer_yin_type(name,_guess=type_from_extension):
    # XXX This is not very efficient
    ext = os.path.splitext(name)
    if YIN_FILE_REGEX.match(name):
        return YIN_MIME_TYPE
    if len(ext) and ext[1]:
        return _guess(name)

logger.debug('Using %s for mime-type detection' % infer_yin_type.__module__)

class Object:
    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path

        if os.path.isdir(self.path):
            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None

            self.type = infer_yin_type(self.name, type_from_extension)

    @staticmethod
    def get_objects(path):
        objects = []

        if path:
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                objects.append(Object(object_path))

        return objects

